// Unicode White_Space predicate and Python-compatible strip helpers.
//
// CPython's str.strip() (no argument) removes characters for which
// Py_UNICODE_ISSPACE() is true.  That predicate is exactly the Unicode
// White_Space property, which Node exposes as \p{White_Space}.
//
// Notably this set INCLUDES U+0085 (NEL), U+00A0 (NBSP), U+1680, U+2000..U+200A,
// U+2028, U+2029, U+202F, U+205F and U+3000, and EXCLUDES U+001C..U+001F,
// U+180E (White_Space only up to Unicode 6.2), U+200B (ZWSP) and U+FEFF (BOM).
//
// JavaScript's \s is NOT a substitute: it matches U+FEFF and misses U+0085.

const WHITE_SPACE_RE = /^\p{White_Space}$/u;

/**
 * True when `ch` (a single code point, given as a string) has the Unicode
 * White_Space property.
 * @param {string} ch
 * @returns {boolean}
 */
export function isPyWhitespaceChar(ch) {
  return typeof ch === 'string' && ch.length > 0 && WHITE_SPACE_RE.test(ch);
}

/**
 * True when the code point `cp` has the Unicode White_Space property.
 * @param {number} cp
 * @returns {boolean}
 */
export function isPyWhitespaceCodePoint(cp) {
  if (!Number.isInteger(cp) || cp < 0 || cp > 0x10ffff) return false;
  return WHITE_SPACE_RE.test(String.fromCodePoint(cp));
}

/**
 * Split a string into an array of code points (never splits surrogate pairs).
 * @param {string} s
 * @returns {string[]}
 */
export function toCodePoints(s) {
  return Array.from(s);
}

/**
 * Python `s.strip()` -- remove leading and trailing White_Space code points.
 * Operates on code points so astral characters are never cut in half.
 * @param {string} s
 * @returns {string}
 */
export function pyStrip(s) {
  const cps = toCodePoints(s);
  let start = 0;
  let end = cps.length;
  while (start < end && isPyWhitespaceChar(cps[start])) start += 1;
  while (end > start && isPyWhitespaceChar(cps[end - 1])) end -= 1;
  return cps.slice(start, end).join('');
}

/**
 * Python `s.lstrip()`.
 * @param {string} s
 * @returns {string}
 */
export function pyLStrip(s) {
  const cps = toCodePoints(s);
  let start = 0;
  while (start < cps.length && isPyWhitespaceChar(cps[start])) start += 1;
  return cps.slice(start).join('');
}

/**
 * Python `s.rstrip()`.
 * @param {string} s
 * @returns {string}
 */
export function pyRStrip(s) {
  const cps = toCodePoints(s);
  let end = cps.length;
  while (end > 0 && isPyWhitespaceChar(cps[end - 1])) end -= 1;
  return cps.slice(0, end).join('');
}

// Unicode decimal-digit (general category Nd) predicate plus numeric value.
//
// Python's int() accepts ANY Unicode decimal digit, not just ASCII 0-9, and
// mixed scripts are allowed ('9' + U+1D7DD == 95).  Categories Nl (e.g. Roman
// numerals) and No (e.g. superscripts, vulgar fractions) are rejected.
//
// Node has no API that exposes a code point's decimal value, so we derive it:
// Nd code points always come in contiguous, 10-aligned runs of 0..9, so we walk
// backwards to the start of the run and take the offset modulo 10.  The modulo
// is essential -- U+1D7CE..U+1D7FF is a single 50-code-point Nd run containing
// five separate 0..9 blocks.

const ND_RE = /^\p{Nd}$/u;

/**
 * True when `ch` (a single code point, given as a string) is in category Nd.
 * @param {string} ch
 * @returns {boolean}
 */
export function isDecimalDigitChar(ch) {
  return typeof ch === 'string' && ch.length > 0 && ND_RE.test(ch);
}

/**
 * True when code point `cp` is in category Nd.
 * @param {number} cp
 * @returns {boolean}
 */
export function isDecimalDigitCodePoint(cp) {
  if (!Number.isInteger(cp) || cp < 0 || cp > 0x10ffff) return false;
  return ND_RE.test(String.fromCodePoint(cp));
}

// Memoise run starts so repeated lookups on long numbers stay cheap.
const runStartCache = new Map();

/**
 * Numeric value (0..9) of a Unicode decimal digit code point.
 * @param {number} cp
 * @returns {number} 0..9, or -1 when `cp` is not a decimal digit
 */
export function decimalDigitValueCodePoint(cp) {
  if (!isDecimalDigitCodePoint(cp)) return -1;
  let runStart = runStartCache.get(cp);
  if (runStart === undefined) {
    runStart = cp;
    while (runStart > 0 && isDecimalDigitCodePoint(runStart - 1)) runStart -= 1;
    runStartCache.set(cp, runStart);
  }
  return (cp - runStart) % 10;
}

/**
 * Numeric value (0..9) of a single-code-point decimal-digit string.
 * @param {string} ch
 * @returns {number} 0..9, or -1 when `ch` is not a decimal digit
 */
export function decimalDigitValue(ch) {
  if (typeof ch !== 'string' || ch.length === 0) return -1;
  const cp = ch.codePointAt(0);
  // Reject multi-code-point input.
  if (String.fromCodePoint(cp) !== ch) return -1;
  return decimalDigitValueCodePoint(cp);
}
